/**
 * @method
 * @name ipt_efCpCpnIntRt_2_onblur
 * @description ipt_efCpCpnIntRt_2 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_efCpCpnIntRt_2_onblur = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.setCpIsuNm(selfVar.form, '' + dma_pageContext.get("p") + '');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10801.ipt_efCpCpnIntRt_2_onblur' }); }
};

