///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCpIsuNm
 * @description set Cp Isu Nm 처리
 * @param {*} fm fm
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCpIsuNm = async function (fm, idx) {
    if ($c.str.getByteLength(fm["ef_cp_cpn_int_rt"+idx].value) > 0 && $c.str.getByteLength(fm["ef_cp_cpn_int_rt"+idx].value) !== 6) {
        await $c.win.alert("표면이자율 입력시\n입력예에 따라 소수점 포함해서 6자리[예:09.090]로 입력바랍니다.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if ($c.num.isNumber(fm["ef_cp_cpn_int_rt"+idx])) {
        if ($c.str.getByteLength(fm["ef_cp_cpn_int_rt"+idx].value) !== 0) {
            fm["ef_cp_isu_nm"+idx].value = '국고채이자 ' + Del_Point2(fm["ef_cp_cpn_int_rt"+idx]) + '-' + fm["ef_cp_rdmp_dt"+idx].value.substring(2, 6);
            fm["ef_fisn_val"+idx].value = 'KTB/Disc STRIPS IR ' + fm["ef_cp_rdmp_dt"+idx].value + ' Sr Gtd';
        } else {
            fm["ef_cp_isu_nm"+idx].value = '';
            fm["ef_fisn_val"+idx].value = '';
        }
    }
};

/**
 * @method
 * @name setParSumAmt
 * @description set Par Sum Amt 처리
 * @param {*} fm fm
 * @param {Number} idx idx
 * @param {Array} rows rows
 * @returns {void}
 * @hidden N
 */
scwin.setParSumAmt = function (fm, idx, rows) {
    if ($c.str.getByteLength(fm["ef_cp_par_tot_amt"+idx].value) > 0) {
        $c.num.formatNumber(fm["ef_cp_par_tot_amt"+idx]);
        for (idx1 = idx; idx1 < rows; idx1++) {
            fm["ef_cp_par_tot_amt"+idx1].value = fm["ef_cp_par_tot_amt"+idx].value;
        }
    }
};

/**
 * @method
 * @name CheckValues
 * @description Check Values 처리
 * @param {*} fm fm
 * @param {Array} rows rows
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.CheckValues = async function (fm, rows) {
    if (await scwin.SendCheckData(fm, rows)) {
        for (idx = 0; idx < rows; idx++) {
            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String('input[name=ef_cp_rdmp_dt' + idx + ']').replace(/^#/, ''))) || { setValue: function () {} }).setValue($('input[name=ef_cp_rdmp_dt' + idx + ']').val());
            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String('input[name=ef_cp_cpn_int_rt' + idx + ']').replace(/^#/, ''))) || { setValue: function () {} }).setValue($('input[name=ef_cp_cpn_int_rt' + idx + ']').val());
            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String('input[name=ef_cp_par_tot_amt' + idx + ']').replace(/^#/, ''))) || { setValue: function () {} }).setValue($('input[name=ef_cp_par_tot_amt' + idx + ']').val());
            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String('input[name=ef_cp_isu_nm' + idx + ']').replace(/^#/, ''))) || { setValue: function () {} }).setValue($('input[name=ef_cp_isu_nm' + idx + ']').val());
            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String('input[name=ef_fisn_val' + idx + ']').replace(/^#/, ''))) || { setValue: function () {} }).setValue($('input[name=ef_fisn_val' + idx + ']').val());
        }
        $c.win.closePopup();
    }
};

/**
 * @method
 * @name SendCheckData
 * @description Send Check Data 처리
 * @param {*} fm fm
 * @param {Array} rows rows
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.SendCheckData = async function (fm, rows) {
    for (idx = 0; idx < rows; idx++) {
        if ($c.str.getByteLength($('input[name=ef_cp_cpn_int_rt' + idx + ']').val()) === 0) {
            await $c.win.alert((idx + 1) + "번째 열의 표면이자율을 입력하십시오.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
        if ($c.str.getByteLength($('input[name=ef_cp_par_tot_amt' + idx + ']').val()) === 0) {
            await $c.win.alert((idx + 1) + "번째 열의 액면총액을 입력하십시오.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name winClose
 * @description win Close 처리
 * @returns {void}
 * @hidden N
 */
scwin.winClose = function () {
    $c.win.closePopup();
};
